a=open('probe.xm','rb').read()
b=open('probe2.xm','rb').read()
print(len(a), len(b))
# find first diff
for i in range(min(len(a),len(b))):
    if a[i]!=b[i]:
        print('first diff at', i, hex(a[i]), hex(b[i]))
        break
# diff run lengths
i=0; runs=[]
while i<len(b):
    if i>=len(a) or a[i]!=b[i]:
        j=i
        while j<len(b) and (j>=len(a) or a[j]!=b[j]):
            j+=1
        runs.append((i,j-i))
        i=j
    else:
        i+=1
print(runs[:20])
EOF"}

