{"command":"cd /workspace/work && python3 << 'PYEOF'
import json
a=json.load(open('song_final7.json'))
b=json.load(open('song_final8.json'))
# find cells whose volume actually changed and check their new values
diffs=0; maxvol=0
for x,y in zip(a,b):
    if x.get('name')=='pattern_set_cell' and y.get('name')=='pattern_set_cell':
        if x['arguments'].get('volume')!=y['arguments'].get('volume'):
            diffs+=1
            maxvol=max(maxvol, y['arguments']['volume'])
print('cells with changed volume', diffs, 'max new vol', maxvol)
# sanity: which instruments had which old/new vols
from collections import Counter
c=Counter()
for x,y in zip(a,b):
    if x.get('name')=='pattern_set_cell':
        ov=x['arguments'].get('volume'); nv=y['arguments'].get('volume')
        if ov!=nv:
            c[(x['arguments']['instrument'],ov,nv)]+=1
print(c)
PYEOF"}

